const D = { energy: .62, scale: 1, speed: 1, density: .5, division: .6, hue: 135, x: .5, y: .5, style: 'fluor', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// A live-cell timelapse of a proliferating epithelium. Cells tile the field as a
// jittered sheet of rounded membranes with visible junctions and a stained
// nucleus each. A mitotic wave travels across the tissue on a moving diagonal
// front: as it passes, cells run the division programme -- interphase nucleus ->
// condensed metaphase plate -> anaphase nuclei pulling apart while the cell
// elongates -> a cleavage furrow pinches it into two daughters -- then relax back.
// Because the wave keeps moving and each cell carries its own rate, divisions
// ripple endlessly and never converge; scattered apoptosis darkens and shrinks
// the odd cell so the sheet keeps churning. Offered as GFP/DAPI fluorescence,
// H&E histology, phase-contrast, or a flat segmentation label-map.
// -----------------------------------------------------------------------------

const u = Math.min(width, height);
const sp = 0.25 + P.speed * 0.9;
const divAmt = 0.2 + P.division * 1.1;

const sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7 + 2.1) * 43758.5453; return s - Math.floor(s); };

// build the cell sheet on seed / density change -------------------------------
const cols = Math.round(9 + P.density * 15);
const rows = Math.max(4, Math.round(cols * height / width));
if (!S.cell || S.seedUsed !== P.seed || S.cols !== cols || S.rows !== rows) {
  S.seedUsed = P.seed; S.cols = cols; S.rows = rows;
  S.cell = [];
  for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) {
    const k = j * cols + i;
    const stag = (j % 2) * 0.5;                       // brick offset -> tissue, not grid
    S.cell.push({
      gx: (i + 0.5 + stag) / cols, gy: (j + 0.5) / rows,
      jx: (fr(k * 3 + 1) - 0.5) * 0.6 / cols, jy: (fr(k * 5 + 2) - 0.5) * 0.6 / rows,
      sz: 0.78 + fr(k * 7 + 3) * 0.34,
      off: fr(k * 11 + 4), rate: 0.02 + fr(k * 13 + 5) * 0.05,
      axis: fr(k * 17 + 6) * Math.PI,
      aoff: fr(k * 19 + 7), arate: 0.02 + fr(k * 23 + 8) * 0.03,
      wob: fr(k * 29 + 9) * 6.283, hueJ: (fr(k * 31 + 10) - 0.5) * 30,
      lab: fr(k * 37 + 11)
    });
  }
}

const t = K.t;
const style = P.style;
const glow = 0.4 + P.energy * 1.2 + A.rms * 0.3;
const waveK = 2.4 + P.density * 3;
const wavePhase = t * sp * 0.55;

// palette / mode
let bgH, bgS, bgB, mode;
if (style === 'histo') { bgH = 328; bgS = 20; bgB = 78; mode = 'histo'; }
else if (style === 'phase') { bgH = 210, bgS = 6; bgB = 46; mode = 'phase'; }
else if (style === 'segmented') { bgH = 220; bgS = 30; bgB = 11; mode = 'segmented'; }
else { bgH = 225; bgS = 55; bgB = 12; mode = 'fluor'; }
const pale = (mode === 'histo');

const cw = width / cols, chh = height / rows;
const cellR = Math.min(cw, chh) * 0.5 * P.scale;

push();
noStroke(); rectMode(CENTER);
fill(bgH, bgS, bgB); rect(width / 2, height / 2, width * 1.02, height * 1.02);

if (mode === 'fluor' || mode === 'segmented') blendMode(mode === 'fluor' ? ADD : BLEND);

// membrane / nucleus colours per style
const memH = mode === 'histo' ? 320 : (mode === 'phase' ? 210 : P.hue);
for (let ci = 0; ci < S.cell.length; ci++) {
  const c = S.cell[ci];
  // apoptosis window -> shrink + darken
  const apo = (c.aoff + t * c.arate * sp) % 1;
  const dying = apo < 0.09 ? (1 - apo / 0.09) : 0;
  const alive = 1 - dying * 0.92;
  // mitotic phase driven by own rate + the travelling wave
  const wv = 0.5 * (1 + Math.sin(c.gx * 6.2831853 * waveK * 0.16 - wavePhase + c.gy * 2.1));
  let p = (c.off + t * c.rate * sp + divAmt * 0.42 * wv) % 1;
  const cx = c.gx * width + c.jx * width + Math.sin(t * 0.4 * sp + c.wob) * cw * 0.05;
  const cy = c.gy * height + c.jy * height + Math.cos(t * 0.37 * sp + c.wob) * chh * 0.05;
  const R = cellR * c.sz * alive;
  if (R < 1.5) continue;

  const hue = (memH + c.hueJ + 360) % 360;
  let mS, mB, nucH, nucS, nucB;
  if (mode === 'histo') { mS = 30; mB = 40; nucH = 285; nucS = 55; nucB = 34; }
  else if (mode === 'phase') { mS = 4; mB = 70 * glow * (0.7 + 0.3 * wv); nucH = 210; nucS = 6; nucB = 22; }
  else if (mode === 'segmented') { const lh = (c.lab * 360) | 0; mS = 55; mB = 60; nucH = lh; nucS = 40; nucB = 82; }
  else { mS = 70; mB = Math.min(100, 50 * glow); nucH = 220; nucS = 65; nucB = Math.min(100, 62 * glow); }

  push(); translate(cx, cy); rotate(c.axis);

  // ---- membrane ----
  const elong = 1 + Math.max(0, p - 0.62) * (p > 0.62 ? divAmt * 1.3 : 0);
  const furrow = p > 0.8 ? (p - 0.8) / 0.2 : 0;             // cleavage furrow depth
  const mw = Math.max(1, R * 1.86 * elong), mh = Math.max(1, R * 1.86 / Math.sqrt(elong));
  const rad = R * 0.7;
  if (mode === 'segmented') { noStroke(); fill(nucH, mS, mB, 100); }
  else if (pale) { noStroke(); fill(hue, mS, mB + 34, 60); }
  else { noStroke(); fill(hue, mS, mB * 0.5, 26 + glow * 8); }
  // cell body (rounded)
  if (furrow < 0.5) { rect(0, 0, mw, mh, rad); }
  else { // two daughter lobes
    const gap = furrow * R * 0.9;
    rect(-gap - R * 0.5, 0, Math.max(1, R * 1.6), mh * 0.92, rad);
    rect(gap + R * 0.5, 0, Math.max(1, R * 1.6), mh * 0.92, rad);
  }
  // membrane outline (junction)
  noFill(); strokeWeight(Math.max(0.6, R * 0.09));
  if (mode === 'segmented') stroke(0, 0, 100, 90);
  else if (pale) stroke(hue, mS + 20, 24, 70);
  else stroke(hue, mS, Math.min(100, mB * 1.5), 80);
  if (furrow < 0.5) rect(0, 0, mw, mh, rad);
  else { const gap = furrow * R * 0.9; rect(-gap - R * 0.5, 0, Math.max(1, R * 1.6), mh * 0.92, rad); rect(gap + R * 0.5, 0, Math.max(1, R * 1.6), mh * 0.92, rad); }

  // ---- nucleus / chromosomes by phase ----
  noStroke();
  const flash = mode === 'fluor' ? (1 + (p > 0.62 && p < 0.92 ? 0.7 : 0)) : 1;
  if (p < 0.62) {
    // interphase: single round nucleus + faint nucleolus
    for (let g2 = 3; g2 >= 1; g2--) { fill(nucH, nucS, nucB * flash, mode === 'fluor' ? 24 : (pale ? 80 : 60)); ellipse(0, 0, R * (0.5 + g2 * 0.12), R * (0.5 + g2 * 0.12)); }
    if (R > u * 0.02) { fill(nucH, nucS + 15, nucB * 0.7, pale ? 70 : 50); ellipse(R * 0.08, -R * 0.06, R * 0.16, R * 0.16); }
  } else if (p < 0.78) {
    // prophase/metaphase: condensed chromosomes on a bright equatorial plate
    const nc = 5;
    for (let g2 = 0; g2 < nc; g2++) { const yy = (g2 / (nc - 1) - 0.5) * R * 0.7; fill(nucH, nucS + 10, Math.min(100, nucB * 1.2 * flash), pale ? 85 : 70); ellipse(0, yy, R * 0.22, R * 0.12); }
  } else {
    // anaphase/telophase: two nuclei pulling apart along the axis
    const sepr = (p - 0.78) / 0.22 * R * (0.9 + divAmt * 0.4);
    for (const dir of [-1, 1]) { for (let g2 = 2; g2 >= 1; g2--) { fill(nucH, nucS, nucB * flash, mode === 'fluor' ? 30 : (pale ? 82 : 62)); ellipse(dir * (sepr + R * 0.5), 0, R * (0.34 + g2 * 0.1), R * (0.34 + g2 * 0.1)); } }
  }
  pop();
}
if (mode === 'fluor' || mode === 'segmented') blendMode(BLEND);

// travelling-wave sheen (broad, low-alpha -> carries motion + reads as the front)
if (!pale) { noStroke(); blendMode(mode === 'segmented' ? BLEND : ADD);
  for (let b = 0; b < 3; b++) { const wx = ((wavePhase * 0.5 + b * 0.33) % 1); fill(memH, 40, 40 * glow, 6); rect((wx) * width, height / 2, width * 0.16, height * 1.1); }
  blendMode(BLEND); }

pop();
if (P.alpha < 100) { push(); noStroke(); rectMode(CORNER); fill(bgH, bgS, bgB, 100 - Math.max(0, Math.min(100, P.alpha))); rect(0, 0, width, height); pop(); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
